def min_time_to_deliver_candies(n, m, candies):
    # Initialize the distance matrix with infinity
    dist = [[float('inf')] * n for _ in range(n)]

    # Set the distance from a station to itself as 0
    for i in range(n):
        dist[i][i] = 0

    # Set the distance between directly connected stations as 1
    for a, b in candies:
        dist[a-1][b-1] = 1

    # Floyd-Warshall algorithm to find the shortest paths between all pairs of stations
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Calculate the minimum time for each starting station
    min_times = []
    for start in range(n):
        total_time = 0
        for a, b in candies:
            # Calculate the shortest path from start to a, then to b
            total_time += dist[start][a-1] + dist[a-1][b-1]
        min_times.append(total_time)

    return min_times

# Read input
n, m = map(int, input().split())
candies = [tuple(map(int, input().split())) for _ in range(m)]

# Calculate and print the result
result = min_time_to_deliver_candies(n, m, candies)
